sections.body:
保存为 bark-selector.mjs，用 node bark-selector.mjs 运行。目录顺序由作者确定；选择第一个满足条件、且不是上一句的条目。没有候选就返回 null，保持安静。这里刻意不加随机性，方便复现；它不是完整对话系统。

```javascript
/**
 * @file Demonstrate approved NPC bark selection from declared narrative facts.
 * @author liliwei
 * @date 2026-11-03
 * @LastEditors liliwei
 * @LastEditTime 2026-11-03
 */
const factIds = new Set(['storm', 'cave', 'culprit']);

/**
 * Pick the first eligible line from an editorially ordered, validated catalog.
 * @param {Array<object>} lines Reviewed rows; each has id, speaker, text, facts, approved.
 * @param {object} state Trusted snapshot: speaker, speakerFacts, playerFacts, lastId.
 * @returns {object|null} Original catalog row, or null to remain silent. Does not mutate inputs.
 */
export function pickBark(lines, state) {
  const known = new Set(state.speakerFacts);
  const revealed = new Set(state.playerFacts);
  return lines.find(line =>
    line.approved === true &&
    line.speaker === state.speaker &&
    line.id !== state.lastId &&
    Array.isArray(line.facts) &&
    line.facts.every(id =>
      factIds.has(id) && known.has(id) && revealed.has(id)
    )
  ) ?? null;
}

// Original teaching text. Ordering and approval are human decisions.
export const lines = [
  {id: 'recap', speaker: 'keeper', facts: ['culprit'],
    text: '船长竟参与走私，真让人难过。', approved: true},
  {id: 'route', speaker: 'keeper', facts: ['cave'],
    text: '那处海洞的入口很窄。', approved: true},
  {id: 'weather', speaker: 'keeper', facts: ['storm'],
    text: '那场风暴真大，想起来还后怕。', approved: true},
  {id: 'draft', speaker: 'keeper', facts: ['storm'],
    text: '这句尚未审核。', approved: false},
];
export const base = {
  speaker: 'keeper', speakerFacts: ['storm', 'cave'],
  playerFacts: ['storm'], lastId: null,
};
export const scenarios = [
  base,
  {...base, playerFacts: ['storm', 'cave']},
  {...base, playerFacts: ['storm', 'cave', 'culprit']},
  {...base, speakerFacts: ['storm', 'cave', 'culprit']},
  {...base, lastId: 'weather'},
];
console.log(scenarios.map(state => pickBark(lines, state)?.id ?? null));
```

传入的是已经校验结构的目录与任务系统快照。导入阶段还应检查唯一 ID、非空文本、合法角色、语言及剧情版本，禁止稀疏数组等异常结构；此短函数不是通用 JSON 校验器。facts=[] 可用于经人确认不含剧情事实的问候，不代表任意文字都能留空标签。返回对象来自原目录，调用方只读使用。

lastId 只避免连续重复同一句，不实现播放冷却、语音队列或跨 NPC 去重。调用方应在实际展示后记录它，未展示或资源加载失败时不更新；若只剩上一句，本例选择沉默。
